import {creatorSave,verifyHistory,LIMITS} from './creator-history.mjs';
import {seal,verifyReceipt,canonical} from './core.js';
const SCHEMA='reckoner.creator-history-bundle.v1',encoder=new TextEncoder();
const need=(v,m)=>{if(!v)throw Error(m);};
const fields=(v,n)=>need(v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join(',')===n.sort().join(','),'Unexpected history bundle fields');
function encode(bytes){let text='';for(let i=0;i<bytes.length;i+=16384)text+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(text);}
function decode(text){need(typeof text==='string'&&text.length<=Math.ceil(LIMITS.csvBytes/3)*4&&/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(text),'Invalid snapshot encoding');const raw=atob(text);return Uint8Array.from(raw,c=>c.charCodeAt(0));}
export function bundleText(result){return JSON.stringify({schema:SCHEMA,history:result.historyJson,snapshots:[...result.snapshots].map(([sha256,bytes])=>({sha256,base64:encode(bytes)}))});}
export async function openBundle(text,expected={}){
 need(typeof text==='string'&&text.length<=92*1024*1024,'History bundle byte budget');const bundle=JSON.parse(text);fields(bundle,['schema','history','snapshots']);need(bundle.schema===SCHEMA&&Array.isArray(bundle.snapshots)&&bundle.snapshots.length<=200,'History bundle schema/count');const snapshots=new Map();let total=0;
 for(const snapshot of bundle.snapshots){fields(snapshot,['sha256','base64']);need(typeof snapshot.sha256==='string'&&!snapshots.has(snapshot.sha256),'Duplicate snapshot');const bytes=decode(snapshot.base64);total+=bytes.length;need(total<=LIMITS.totalBytes,'Snapshot aggregate budget');snapshots.set(snapshot.sha256,bytes);}
 const verification=await verifyHistory(bundle.history,snapshots,expected),history=JSON.parse(bundle.history),last=history.entries.at(-1);const state=await verifyReceipt(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(snapshots.get(last.body.receipt.sha256))));return {historyJson:bundle.history,snapshots,verification,state};
}
export function isHistoryBundle(value){return value?.schema===SCHEMA;}
// The async content-addressed adapter commits immutable objects, version references and
// its retained head in one IndexedDB transaction under the cooperating-tab Web Lock.
// The legacy adapter retains its version-first/head-last behavior. Neither contract
// establishes filesystem durability or protection against malicious same-origin writers.
// Retained checkpoints are independent local references, not signatures.
export function createHistoryStore(storage,prefix='reckoner-creator-history:',locks=globalThis.navigator?.locks){
 const headKey=id=>prefix+'head:'+id,expectedCheckpoints=new Map();
 const checkpointOf=head=>head?{genesis:head.genesis,tip:head.tip}:null;
 function bindDraft(state){const checkpoint=state.creatorHistoryCheckpoint??null;if(checkpoint!==null){fields(checkpoint,['genesis','tip']);need([checkpoint.genesis,checkpoint.tip].every(x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x)),'Invalid draft base checkpoint');}expectedCheckpoints.set(state.id,structuredClone(checkpoint));}
 function watchDraft(state){if(!expectedCheckpoints.has(state.id))bindDraft(state);}
 function expectedCheckpoint(id){return structuredClone(expectedCheckpoints.get(id)??null);}
 async function acceptLoaded(checked,beforeAdopt=()=>{}){const id=checked.state.id;await storage.ready?.(id);need(typeof locks?.request==='function','This browser cannot serialize creator-history recovery. Download draft recovery and use a current supported browser.');return locks.request(prefix+'commit:'+id,{mode:'exclusive'},async()=>{const {head}=await readHead(id);need(head&&head.genesis===checked.verification.genesis&&head.tip===checked.verification.tip,'History changed during recovery; reopen latest saved history');await beforeAdopt();const current=(await readHead(id)).head;need(current&&current.genesis===checked.verification.genesis&&current.tip===checked.verification.tip,'History changed during recovery; reopen latest saved history');expectedCheckpoints.set(id,checkpointOf(current));});}

 async function matchesRetained(checked){const {head}=await readHead(checked.state.id);return Boolean(head&&head.genesis===checked.verification.genesis&&head.tip===checked.verification.tip);}
 async function adoptDraft(id,beforeAdopt){await storage.ready?.(id);need(typeof locks?.request==='function','This browser cannot serialize draft recovery. Download recovery and use a current supported browser.');return locks.request(prefix+'commit:'+id,{mode:'exclusive'},async()=>{const baseline=(await readHead(id)).raw;await beforeAdopt();need((await readHead(id)).raw===baseline,'History changed during draft recovery. No checkpoint was adopted.');});}
 function retainsSavedEntries(state,prior){for(const key of ['revisions','reviews','connections','modelRuns','resolutions','contextDefinitions','contextEvents','assertions','assertionReviews']){const incoming=new Map((state[key]||[]).map(entry=>[key==='contextDefinitions'?entry.id+':'+entry.version:entry.id,entry]));for(const entry of prior[key]||[]){const id=key==='contextDefinitions'?entry.id+':'+entry.version:entry.id;need(incoming.has(id)&&canonical(incoming.get(id))===canonical(entry),'This draft omits or changes retained saved '+key+'. Recover or merge the latest creator history before saving.');}}const notes=new Map((state.context.archiveActivity?.events||[]).map(entry=>[entry.id,entry]));for(const entry of prior.context.archiveActivity?.events||[])need(notes.has(entry.id)&&canonical(notes.get(entry.id))===canonical(entry),'This draft omits or changes retained Archive activity notes. Recover or merge the latest creator history before saving.');}
 function storageFailure(cause){if(['QuotaExceededError','SecurityError','InvalidStateError'].includes(cause?.name)){const error=Error('Local history storage unavailable: '+cause.message);error.code='HISTORY_STORAGE_WRITE_UNAVAILABLE';error.cause=cause;return error;}return cause;}
 async function writeRetained(key,value){try{await storage.setItem(key,value);}catch(cause){throw storageFailure(cause);}}
 async function readRetained(key){try{return await storage.getItem(key);}catch(cause){throw storageFailure(cause);}}
 async function readHead(id){const raw=await readRetained(headKey(id));if(raw===null)return {raw:null,head:null};const head=JSON.parse(raw);fields(head,['genesis','tip','version']);need([head.genesis,head.tip].every(x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x))&&head.version===prefix+'version:'+id+':'+head.tip,'Invalid retained checkpoint');return {raw,head};}
 async function load(id){const {head}=await readHead(id);if(!head)return null;const text=await readRetained(head.version);need(typeof text==='string','Retained history snapshot missing; preserve storage and recover from your exported bundle');const checked=await openBundle(text,{expectedGenesis:head.genesis,expectedTip:head.tip});need(checked.state.id===id&&checked.verification.recordId===id,'Retained history record ID does not match requested record');return checked;}
 async function prepare(state,creatorLabel,csvBytes=null){state=structuredClone(state);watchDraft(state);csvBytes=csvBytes===null?null:new Uint8Array(csvBytes);const baseline=await readHead(state.id);need(canonical(checkpointOf(baseline.head))===canonical(expectedCheckpoint(state.id)),'Creator checkpoint changed since this draft was opened. Download draft recovery, then recover or merge the latest saved history before saving.');const prior=await load(state.id);if(prior)retainsSavedEntries(state,prior.state);const receiptBytes=encoder.encode(JSON.stringify(await seal(state)));const result=await creatorSave({historyJson:prior?.historyJson??null,snapshots:prior?.snapshots??new Map(),receiptBytes,csvBytes,creatorLabel,savedAt:new Date().toISOString(),expectedGenesis:prior?.verification.genesis??null,expectedTip:prior?.verification.tip??null});return {recordId:state.id,baseline:baseline.raw,text:bundleText(result),verification:result.verification};}
 async function prepareImport(text){const parsed=await openBundle(text),baseline=await readHead(parsed.state.id);if(baseline.head){need(parsed.verification.genesis===baseline.head.genesis,'Different genesis from this device’s retained checkpoint');const entries=JSON.parse(parsed.historyJson).entries;if(!entries.some(x=>x.sha256===baseline.head.tip)){const retained=await load(parsed.state.id),older=JSON.parse(retained.historyJson).entries.some(x=>x.sha256===parsed.verification.tip);const error=Error(older?'Older history: this backup is valid, but this device retains a later saved history. Nothing was replaced. Recover the latest saved history for this record, or keep this older file for historical inspection.':'Another branch: this backup is valid, but it does not include this device’s latest saved history. Nothing was replaced. Preserve both copies for reconciliation.');error.code=older?'HISTORY_IMPORT_OLDER':'HISTORY_IMPORT_BRANCH';error.recordId=parsed.state.id;error.retainedTip=baseline.head.tip;error.incomingTip=parsed.verification.tip;throw error;}}return {recordId:parsed.state.id,baseline:baseline.raw,text,verification:parsed.verification,state:parsed.state,firstSeen:!baseline.head};}
 async function commit(prepared,beforeCommit=()=>{}){await storage.ready?.(prepared.recordId);need(typeof locks?.request==='function','This browser cannot serialize creator-history saves. Keep this draft and use a current browser with Web Locks (HTTPS or localhost). No checkpoint was changed.');return locks.request(prefix+'commit:'+prepared.recordId,{mode:'exclusive'},async()=>{need((await readHead(prepared.recordId)).raw===prepared.baseline,'History changed in another tab. Reopen before saving.');const checked=await openBundle(prepared.text,{expectedGenesis:prepared.verification.genesis,expectedTip:prepared.verification.tip});need((await readHead(prepared.recordId)).raw===prepared.baseline,'History changed in another tab. Reopen before saving.');need(checked.verification.recordId===prepared.recordId,'Prepared record ID mismatch');await beforeCommit();need((await readHead(prepared.recordId)).raw===prepared.baseline,'History changed before final commit. Reopen before saving.');const version=prefix+'version:'+prepared.recordId+':'+checked.verification.tip,raw=JSON.stringify({genesis:checked.verification.genesis,tip:checked.verification.tip,version});if(storage.commitVersion){try{await storage.commitVersion({recordId:prepared.recordId,baseline:prepared.baseline,raw,version,checked});}catch(cause){throw storageFailure(cause);}}else{const existing=await readRetained(version);need(existing===null||existing===prepared.text,'Retained version differs; preserve evidence');await writeRetained(version,prepared.text);need(await readRetained(version)===prepared.text,'History write read-back failed');await writeRetained(headKey(prepared.recordId),raw);need(await readRetained(headKey(prepared.recordId))===raw,'Checkpoint read-back failed; reopen retained history before retrying');}expectedCheckpoints.set(prepared.recordId,checkpointOf({genesis:checked.verification.genesis,tip:checked.verification.tip}));return checked;});}
 async function readOnlyExport(id){if(storage.readOnlyBundle)return storage.readOnlyBundle(id);const checked=await load(id);return checked?{text:bundleText(checked),verification:checked.verification}:null;}
 async function backupDraft(raw){need(typeof storage.backupDraft==='function','Opaque draft backup unavailable; no draft replaced.');return storage.backupDraft(raw);}
 return {load,prepare,prepareImport,commit,bindDraft,watchDraft,expectedCheckpoint,acceptLoaded,adoptDraft,matchesRetained,readOnlyExport,backupDraft,supportsDraftBackups:typeof storage.backupDraft==='function',listDraftBackups:()=>{need(typeof storage.listDraftBackups==='function','Preserved draft catalog unavailable');return storage.listDraftBackups();},readDraftBackup:hash=>{need(typeof storage.readDraftBackup==='function','Preserved draft backup unavailable');return storage.readDraftBackup(hash);}};
}
